def txt(b64): return base64.b64decode(b64).decode('utf-8')
def sha(t): return hashlib.sha256(t.encode('utf-8')).hexdigest()
def p(rel): return os.path.join(ROOT, *rel.split('/'))
def falha(m): print('NADA foi alterado.\n  - ' + m + '\n  Me mande o arquivo atual que eu ajusto o script.'); sys.exit(1)
def leia(rel):
    raw = open(p(rel), 'rb').read(); bom = raw.startswith(b'\xef\xbb\xbf'); t = raw[3:].decode('utf-8') if bom else raw.decode('utf-8'); return t.replace('\r\n', '\n'), '\r\n' in t, bom
def grave(rel, t, crlf, bom):
    os.makedirs(os.path.dirname(p(rel)), exist_ok=True); b = (t.replace('\n', '\r\n') if crlf else t).encode('utf-8'); open(p(rel), 'wb').write((b'\xef\xbb\xbf' + b) if bom else b)
if not os.path.exists(p(FS)): falha(f'arquivo não encontrado: {FS} (rode na raiz do projeto)')
fs, crlf, bom = leia(FS)
IMP_A = "import { composeClosingForecast, LINKS_WEIGHT } from '@/lib/dashboard/forecastMath'\n"; IMP_N = IMP_A + "import { ForecastYoY } from './ForecastYoY'\n"
COMENT = "        {/* 6 — este mês × o mesmo mês do ano passado: tabela acumulada + gráficos dia a dia (total e por vertical) */}\n"
L_V2 = "        <ForecastYoY />\n"
L_V1 = "        <ForecastYoY metas={{ anest: goals.byVertical.anest.meta, oft: goals.byVertical.oft.meta, ortop: goals.byVertical.ortop.meta, r1: goals.byVertical.r1.meta }} />\n"
VITAL = "        <VitalBlock total={commercial.forecast} monthly={commercial.monthlyForecast} detail={commercial.forecastDetail} />\n"
BLK_A = VITAL + "      </div>\n"; BLK_N = VITAL + "\n" + COMENT + L_V2 + "      </div>\n"                       # âncora principal: o fim da pilha, logo depois da "Saúde da recorrência"
ALT_A = "      </div>\n\n      <DealsModal query={dealsQ}"; ALT_N = "\n" + COMENT + L_V2 + ALT_A                                    # âncora de reserva: o fim da pilha, logo antes do popup de negócios

def onde_monta():
    achados = []
    base = p('app')
    for r, ds, fns in os.walk(base):
        ds[:] = [d for d in ds if d not in ('node_modules', '.next')]
        for fn in fns:
            if not fn.endswith(('.tsx', '.jsx')): continue
            rel = os.path.relpath(os.path.join(r, fn), ROOT).replace(os.sep, '/')
            try: linhas = open(os.path.join(r, fn), 'rb').read().decode('utf-8', errors='replace').replace('\r', '').split('\n')
            except OSError: continue
            for i, l in enumerate(linhas):
                if '<ForecastSection' in l and 'function ForecastSection' not in l: achados.append((rel, i + 1, l.strip()[:120], (linhas[i - 1].strip()[:120] if i else '')))
    return achados

if UNDO:
    feito = []
    if os.path.exists(p(BAK)):
        if DRY: print(f'(simulação) restauraria {FS} a partir de {BAK}')
        else: shutil.copyfile(p(BAK), p(FS)); os.remove(p(BAK)); feito.append(f'{FS} restaurado')
    for rel, (h, b64) in NOVOS.items():
        if os.path.exists(p(rel)):
            t = leia(rel)[0]
            if t == txt(b64) or sha(t) in ANTERIORES.get(rel, ()):
                if DRY: print(f'(simulação) apagaria {rel}')
                else: os.remove(p(rel)); feito.append(f'{rel} apagado')
            else: print(f'  ! {rel} foi alterado por você: NÃO apaguei')
    for d in ('app/api/dashboard/forecast/yoy',):
        try:
            if not DRY: os.rmdir(p(d))
        except OSError: pass
    print('Desfeito:\n  ' + '\n  '.join(feito) if feito else 'Nada a desfazer.'); sys.exit(0)

