estado = {}                                                                                         # arquivo novo → 'falta' | 'igual' | 'antigo' (versão 1 ou 2) | 'diferente'
for rel, (h, b64) in NOVOS.items():
    t = txt(b64)
    if sha(t) != h: falha(f'este script está corrompido ({rel}): baixe de novo.')
    if not os.path.exists(p(rel)): estado[rel] = 'falta'
    else:
        c = leia(rel)[0]; estado[rel] = 'igual' if c == t else ('antigo' if sha(c) in ANTERIORES.get(rel, ()) else 'diferente')
dif = [r for r, e in estado.items() if e == 'diferente']
if dif: falha('já existe, com conteúdo diferente do que eu criei (nem o de uma versão anterior, nem o desta), e não vou sobrescrever: ' + ', '.join(dif))
tem_imp = IMP_N in fs; tem_v2 = L_V2 in fs; tem_v1 = L_V1 in fs
if 'ForecastYoY' in fs and not ((tem_imp and (tem_v2 or tem_v1))): falha('o ForecastSection.tsx tem só metade da alteração (import sem o bloco, ou o contrário) ou um formato que não reconheço.')
fs_modo = 'ok' if (tem_imp and tem_v2) else ('atualizar' if (tem_imp and tem_v1) else 'inserir')
novo = fs
if fs_modo == 'atualizar': novo = fs.replace(L_V1, L_V2)
elif fs_modo == 'inserir':
    if fs.count(IMP_A) != 1: falha(f"ForecastSection.tsx: esperava 1 linha de import do forecastMath, achei {fs.count(IMP_A)}")
    if fs.count(BLK_A) == 1: novo = fs.replace(IMP_A, IMP_N).replace(BLK_A, BLK_N)
    elif fs.count(ALT_A) == 1: novo = fs.replace(IMP_A, IMP_N).replace(ALT_A, ALT_N)
    else: falha(f'ForecastSection.tsx: não achei o FIM da pilha de blocos (nem o "<VitalBlock … />" seguido do fechamento: {fs.count(BLK_A)}x, nem o "</div>" antes do "<DealsModal": {fs.count(ALT_A)}x)')
a_gravar = [r for r, e in estado.items() if e in ('falta', 'antigo')]
if fs_modo == 'ok' and not a_gravar: print('Já aplicado (versão 7). Nada foi alterado.'); sys.exit(0)
if DRY:
    print('(simulação) nada foi gravado. Faria:')
    for r in a_gravar: print(('  ~ atualizar (versão anterior → v7) ' if estado[r] == 'antigo' else '  + criar ') + r)
    if fs_modo != 'ok': print(f'  ~ {"atualizar o bloco em" if fs_modo == "atualizar" else "alterar"} {FS}' + (f' (cópia em {BAK})' if fs_modo == 'inserir' else ''))
    sys.exit(0)
if fs_modo in ('inserir', 'atualizar'):
    if fs_modo == 'inserir' and not os.path.exists(p(BAK)): shutil.copyfile(p(FS), p(BAK))
    grave(FS, novo, crlf, bom)
for rel in a_gravar: grave(rel, txt(NOVOS[rel][1]), crlf, bom)
print('OK: seção "este mês × ano passado" ' + ('atualizada para a versão 7' if (fs_modo == 'atualizar' or any(estado[r] == 'antigo' for r in estado)) else 'instalada') + ' no Forecast.\n' + '\n'.join(('  ✓ ' + r + (' (atualizado)' if estado[r] == 'antigo' else '')) for r in a_gravar) + (f'\n  ✓ {FS}' if fs_modo != 'ok' else ''))
ond = onde_monta()
print('\nO Forecast é montado em:' + ('' if ond else ' (não achei "<ForecastSection" em app/ — me avise)'))
for rel, n, l, ant in ond: print(f'  {rel}:{n}   {l}' + (f'\n      (linha de cima: {ant})' if ant and ('view' in ant or '&&' in ant or '?' in ant or 'tab' in ant.lower()) else ''))
